 "An empty React project.": "Um projeto React vazio.",
 "An empty repository works best. If the branch is protected on GitHub, type a new one, such as storelib, and Storelib makes it.": "Um repositório vazio funciona melhor. Se o branch estiver protegido no GitHub, digite um novo, como storelib, e a Storelib cria.",
 "An error occurred": "Ocorreu um erro",
 "An error occurred while saving. Please try again.": "Ocorreu um erro ao salvar. Tente de novo.",
 "An error occurred. Please try again.": "Ocorreu um erro. Tente de novo.",
 "An hour after a buyer leaves checkout without paying, if they asked for news. Turn it on in Checkout.": "Uma hora depois de o comprador sair do checkout sem pagar, se ele pediu novidades. Ative em Checkout.",
 "An hour after someone presses Pay and no order comes of it. Only people who ticked “Email me news and offers” at checkout, or are on your list, get it, and it stops the moment they buy.": "Uma hora depois de alguém tocar em Pagar sem que um pedido seja feito. Só recebe quem marcou “Quero receber novidades e ofertas” no checkout ou está na sua lista, e ela para assim que a pessoa compra.",
 "An icon beside the title": "Um ícone ao lado do título",
 "An image beside the title": "Uma imagem ao lado do título",
 "An image or GIF": "Uma imagem ou GIF",
 "An integration connects Storelib to a service you already use: Google Analytics, a pixel for your ads, a shipping or print on demand company.": "Uma integração conecta a Storelib a um serviço que você já usa: Google Analytics, um pixel de anúncios, uma empresa de envio ou de impressão sob demanda.",
 "An invite is already an approval, so this only applies to anyone who asks without one.": "Um convite já é uma aprovação, então isto só vale para quem pede sem convite.",
 "An invite lasts 1 to 365 days.": "Um convite dura de 1 a 365 dias.",
 "An invite link is the only way in.": "Só dá para entrar com link de convite.",
 "An order": "Um pedido",
 "An order, a payout, a dispute, your website or something that isn't working. A real person at Storelib reads every one and replies here.": "Um pedido, um repasse, uma contestação, seu site ou algo que não está funcionando. Uma pessoa de verdade no Storelib lê cada mensagem e responde aqui.",
 "An unticked “Email me with news and offers” box under the email. Only buyers who tick it get your campaigns.": "Uma caixa desmarcada “Quero receber novidades e ofertas por e-mail” abaixo do e-mail. Só quem marca recebe suas campanhas.",
