 "Buy and print labels from the order page at EasyPost's rates. The tracking number goes on the shipment.": "Compre e imprima etiquetas na página do pedido com as tarifas do EasyPost. O código de rastreio vai no envio.",
 "Buy and print labels from the order page at Shippo's rates. The tracking number goes on the shipment.": "Compre e imprima etiquetas na página do pedido com as tarifas do Shippo. O código de rastreio vai no envio.",
 "Buy for {priceLabel}": "Comprar por {priceLabel}",
 "Buy it together": "Compre junto",
 "Buy label · {price}": "Comprar etiqueta · {price}",
 "Buy now and the cart open Storelib checkout. A cart with something to post asks for the address and delivery first.": "Comprar agora e o carrinho abrem o checkout da Storelib. Um carrinho com algo para enviar pede antes o endereço e a entrega.",
 "Buy opens Storelib checkout. Cards and Google Pay, through Stripe.": "Comprar abre o checkout da Storelib. Cartões e Google Pay, pela Stripe.",
 "Buy {title}": "Comprar {title}",
 "Buyer cases": "Casos de compradores",
 "Buyers add it for {amount}, instead of {amount2}.": "Os compradores adicionam por {amount}, em vez de {amount2}.",
 "Buyers add it for {amount}.": "Os compradores adicionam por {amount}.",
 "Buyers are asked by email after they buy, on your schedule in Storelib Reviews.": "Os compradores recebem o pedido por e-mail depois da compra, conforme sua programação no Storelib Reviews.",
 "Buyers ask for a return from their order page, and you approve each one.": "Os compradores pedem a devolução na página do pedido e você aprova cada uma.",
 "Buyers can add up to 4 photos. Each one is checked before it is kept.": "Os compradores podem adicionar até 4 fotos. Cada uma é verificada antes de ser guardada.",
 "Buyers can change their review for": "Os compradores podem alterar a avaliação por",
 "Buyers can choose it": "Os compradores podem escolher",
 "Buyers can collect their order here for free instead of having it shipped.": "Os compradores podem retirar o pedido aqui de graça em vez de receber em casa.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now instead, turn it off.": "Os compradores não poderão mais usá-lo. Pedidos já feitos com ele mantêm o desconto. Para pausar por enquanto, desative-o.",
 "Buyers can no longer use it. Orders already placed with it keep their discount. To stop it for now, turn it off instead.": "Os compradores não poderão mais usá-lo. Pedidos já feitos com ele mantêm o desconto. Para pausar por enquanto, desative-o.",
 "Buyers can still order, and you ship when it's back.": "Os compradores ainda podem pedir, e você envia quando voltar.",
 "Buyers can use it at checkout.": "Os compradores podem usá-lo no checkout.",
 "Buyers can't check out a physical product until it has a rate for their address. Add a zone and a rate below.": "Os compradores não conseguem finalizar um produto físico até ele ter uma tarifa para o endereço deles. Adicione uma zona e uma tarifa abaixo.",
 "Buyers can't check out on your store yet": "Os compradores ainda não conseguem finalizar na sua loja",
 "Buyers can't check out until you do.": "Os compradores só conseguem pagar depois disso.",
 "Buyers can't check out yet": "Os compradores ainda não conseguem finalizar",
 "Buyers can't check out your physical products yet": "Os compradores ainda não conseguem comprar seus produtos físicos",
 "Buyers can't pay at checkout until this is done.": "Os compradores não conseguem pagar até isso estar feito.",
 "Buyers can't pay for anything until this is done.": "Os compradores não pagam nada até isso estar feito.",
 "Buyers choose Card or Cash on delivery at checkout. The order is placed at once and waits to be sent as usual. Mark it as paid from the order when you have the cash. No Storelib fee is taken on these orders.": "Os compradores escolhem Cartão ou Pagamento na entrega no checkout. O pedido é feito na hora e aguarda o envio como de costume. Marque como pago no pedido quando receber o dinheiro. A Storelib não cobra taxa nesses pedidos.",
 "Buyers choose the price": "Os compradores escolhem o preço",
 "Buyers choose what to pay, from your minimum.": "Os compradores escolhem quanto pagar, a partir do seu mínimo.",
 "Buyers create an account or log in before checkout. Signed out visitors can still browse.": "Os compradores criam uma conta ou entram antes do checkout. Visitantes sem login ainda podem navegar.",
 "Buyers keep their files and their access.": "Os compradores mantêm os arquivos e o acesso.",
 "Buyers never see it": "Os compradores nunca veem",
 "Buyers only": "Só compradores",
 "Buyers only see it struck through when it is higher than the price.": "Os compradores só veem riscado quando ele é maior que o preço.",
 "Buyers reply to order emails. Right now replies go to your login email.": "Os compradores respondem aos e-mails de pedido. Agora as respostas vão para seu e-mail de login.",
 "Buyers review from their receipt or their library. Storelib asks them a week after they buy on Storelib, and again a week later if they have not.": "Os compradores avaliam pelo recibo ou pela biblioteca. O Storelib pede uma semana depois da compra no Storelib, e de novo uma semana depois se não avaliarem.",
 "Buyers see it as sold out. Add stock, or let it keep selling when it runs out.": "Os compradores veem como esgotado. Adicione estoque ou deixe continuar vendendo quando acabar.",
 "Buyers see it when they choose pickup": "Os compradores veem ao escolher retirada",
 "Buyers see them as sold out. Add stock, or let them keep selling when they run out.": "Os compradores veem como esgotados. Adicione estoque ou deixe continuar vendendo quando acabarem.",
 "Buyers see these words on the event page and in their receipt.": "Os compradores veem este texto na página do evento e no recibo.",
 "Buyers see “Name a fair price”, starting at your suggested amount.": "Os compradores veem “Diga um preço justo”, começando pelo seu valor sugerido.",
 "Buyers watch these in their library, and pick up where they left off.": "Os compradores assistem na biblioteca e continuam de onde pararam.",
 "Buyers who asked to hear from you when they paid.": "Compradores que pediram para receber novidades suas ao pagar.",
 "Buyers who choose pickup aren't told when they can come.": "Quem escolhe retirada não fica sabendo quando pode vir.",
 "Buyers who did not ask for news. They get emails about what they bought, never one you send to your list.": "Compradores que não pediram novidades. Recebem e-mails sobre o que compraram, nunca os que você envia para a sua lista.",
 "Buyers who did not ask, as contacts only": "Compradores que não pediram, só como contatos",
 "Buyers who did not ask, as profiles only": "Compradores que não pediram, só como perfis",
 "Buyers won't be able to check out yet": "Os compradores ainda não vão conseguir finalizar",
 "Buyers write to it about their orders. The same address your receipts show.": "Os compradores escrevem para ele sobre os pedidos. É o mesmo endereço dos seus recibos.",
