 "Checkout": "Checkout",
 "Checkout always charges your store's own currency and says so next to the total, so a converted price is shown as an estimate.": "O checkout sempre cobra na moeda da sua loja e mostra isso ao lado do total, então um preço convertido é uma estimativa.",
 "Checkout canceled. Nothing changed.": "Checkout cancelado. Nada mudou.",
 "Checkout charges the visitor's currency, the amounts they saw. A currency Storelib can't charge yet is shown for reference, and checkout says it charges yours.": "O checkout cobra na moeda do visitante, os valores que ele viu. Uma moeda que a Storelib ainda não cobra aparece como referência, e o checkout avisa que cobra na sua.",
 "Checkout charges what your store's prices are in, and says so next to the total, so a converted price is always shown as an estimate.": "O checkout cobra na moeda dos preços da loja e informa ao lado do total, então um preço convertido sempre aparece como estimativa.",
 "Checkout for the product they left": "Checkout do produto que deixaram",
 "Checkout has no way to get an order to the buyer, so nobody can buy.": "O checkout não tem como fazer o pedido chegar ao comprador, então ninguém pode comprar.",
 "Checkout is closed until payments are set up again, so buyers cannot pay you in the meantime.": "O checkout fica fechado até os pagamentos serem configurados de novo, então os compradores não conseguem pagar nesse meio-tempo.",
 "Checkout is the page where a buyer types their details and pays. These settings decide what it asks for.": "O checkout é a página onde o comprador digita os dados e paga. Estas configurações decidem o que é pedido.",
