 "Dynamic Favicon": "Favicon dinâmico",
 "E-books": "E-books",
 "EN": "EN",
 "Each charge lands here with its invoice.": "Cada cobrança aparece aqui com a fatura.",
 "Each email goes to each person once, however often they trigger it. Someone who unsubscribes gets nothing more.": "Cada e-mail vai uma vez para cada pessoa, não importa quantas vezes ela acione. Quem se descadastra não recebe mais nada.",
 "Each item is priced by its own weight, then added up.": "Cada item é cobrado pelo próprio peso e depois somado.",
 "Each item pays the price of the step its weight reaches. Two 0.5 {unit} items at a 0 {unit2} step of $3 pay $6.": "Cada item paga o preço da faixa que seu peso atinge. Dois itens de 0,5 {unit} numa faixa de 0 {unit2} de US$ 3 pagam US$ 6.",
 "Each language gets its own address, like yourstore.com/fr.": "Cada idioma tem seu próprio endereço, como yourstore.com/fr.",
 "Each link needs a label and an https:// address.": "Cada link precisa de um rótulo e um endereço https://.",
 "Each new order for this location is sent here": "Cada novo pedido deste local é enviado aqui",
 "Each new order is sent to your own system as a signed request. Set the address in Integrations.": "Cada novo pedido é enviado ao seu próprio sistema como uma solicitação assinada. Defina o endereço em Integrações.",
 "Each new order with items from here is emailed to this partner with the items and the address. You add their tracking number in Orders when they ship.": "Cada novo pedido com itens daqui é enviado por e-mail a este parceiro com itens e endereço. Você adiciona o rastreio deles em Pedidos quando enviarem.",
 "Each order is printed and shipped for you.": "Cada pedido é impresso e enviado por você.",
 "Each order starts it once. The same order never starts it twice.": "Cada pedido inicia uma vez. O mesmo pedido nunca inicia duas vezes.",
 "Each paid order for your CJ location is sent to CJ with the CJ variants you matched, its tracking comes back, and CJ's stock can keep yours in step.": "Cada pedido pago do seu local CJ vai para o CJ com as variantes associadas, o rastreio volta e o estoque do CJ pode manter o seu em dia.",
 "Each paid order for your Gelato location is sent to Gelato with the product and print file you matched, printed near your buyer, and its tracking comes back.": "Cada pedido pago do seu local Gelato vai para o Gelato com o produto e o arquivo associados, é impresso perto do comprador e o rastreio volta.",
 "Each paid order for your Printful location is sent to your Printful store by SKU, and its tracking comes back to your buyer.": "Cada pedido pago do seu local Printful vai para sua loja Printful por SKU, e o rastreio volta para o comprador.",
 "Each paid order for your Printify location is sent to your Printify shop by SKU, and its tracking comes back to your buyer.": "Cada pedido pago do seu local Printify vai para sua loja Printify por SKU, e o rastreio volta para o comprador.",
 "Each paid order is emailed to the location's supplier with the items and the address. Add tracking when they reply.": "Cada pedido pago é enviado por e-mail ao fornecedor do local com itens e endereço. Adicione o rastreio quando responderem.",
 "Each paid order is sent to your https address as JSON, signed with your secret (X-Storelib-Signature).": "Cada pedido pago é enviado ao seu endereço https como JSON, assinado com seu segredo (X-Storelib-Signature).",
 "Each paid order you ship goes to ShipStation. Print the label there and the tracking comes back to your buyer.": "Cada pedido pago que você envia vai para o ShipStation. Imprima a etiqueta lá e o rastreio volta para o comprador.",
 "Each policy is a page of your site, linked from its footer. They start as templates: replace anything in square brackets with your own terms before you publish.": "Cada política é uma página do seu site, com link no rodapé. Elas começam como modelos: troque tudo entre colchetes pelos seus termos antes de publicar.",
 "Each product page shows its own": "Cada página de produto mostra o seu",
 "Each product's stock is counted per location. When an order comes in, it is assigned to the default location, and its stock goes down there.": "O estoque de cada produto é contado por local. Quando chega um pedido, ele vai para o local padrão e o estoque diminui lá.",
 "Each push arrives within seconds, as a draft. Publish when you like it.": "Cada push chega em segundos, como rascunho. Publique quando gostar.",
 "Each question needs an answer.": "Cada pergunta precisa de uma resposta.",
 "Each rule needs a title.": "Cada regra precisa de um título.",
 "Each sale becomes available about {settleDays} days after it is paid. That wait is set by our payment partner for your country and protects against refunds and disputes.": "Cada venda fica disponível cerca de {settleDays} dias depois de paga. Esse prazo é definido pelo nosso parceiro de pagamentos para o seu país e protege contra reembolsos e contestações.",
 "Each sale becomes available after a short settlement wait set by our payment partner for your country.": "Cada venda fica disponível após uma curta espera de liquidação definida pelo nosso parceiro de pagamentos para o seu país.",
 "Each variant has its own quantity, in Variants below.": "Cada variante tem sua própria quantidade, em Variantes abaixo.",
