 "Keep this community?": "Manter esta comunidade?",
 "Memberships renew again as before and the community comes back the way it was. Members are told by email.": "As assinaturas voltam a renovar como antes e a comunidade volta a ser como era. Os membros são avisados por e-mail.",
 "{n, plural, one {# member pays} other {# members pay}} for it. Their memberships are cancelled first, then it is deleted.": "{n, plural, one {# membro paga} other {# membros pagam}} por ela. Primeiro as assinaturas são canceladas, depois ela é excluída.",
