 "Members": "Membros",
 "Members are told about announcements.": "Os membros são avisados sobre os avisos.",
 "Members can comment on posts here.": "Os membros podem comentar as publicações aqui.",
 "Members can read it; nobody can post. Bringing it back makes it a draft.": "Os membros podem ler; ninguém pode publicar. Restaurar transforma em rascunho.",
 "Members can see who else is here.": "Os membros podem ver quem mais está aqui.",
 "Members can still read it. Nobody can post or join until you bring it back. Nothing is deleted.": "Os membros ainda podem ler. Ninguém pode publicar ou entrar até você restaurar. Nada é excluído.",
 "Members earn points when their posts and comments get reactions, and climb levels. A leaderboard shows in the community.": "Os membros ganham pontos quando suas publicações e comentários recebem reações, e sobem de nível. Um ranking aparece na comunidade.",
