 "Of the emails sent in this period, how many were opened.": "Dos e-mails enviados neste período, quantos foram abertos.",
 "Of the emails your automations sent, how many were opened. Some mail apps hide opens, so this is a floor.": "Dos e-mails que suas automações enviaram, quantos foram abertos. Alguns apps escondem as aberturas, então é um mínimo.",
 "Of the people who visited, how many opened a product, how many started a checkout, and how many orders came in. Each step is shown as a share of the one before.": "Das pessoas que visitaram, quantas abriram um produto, quantas iniciaram um checkout e quantos pedidos chegaram. Cada etapa aparece como parte da anterior.",
 "Off": "Desativado",
 "Off each complete set.": "Em cada conjunto completo.",
 "Off every product in each complete set.": "Em cada produto de cada conjunto completo.",
 "Off for things you hand over yourself.": "Desative para o que você entrega pessoalmente.",
 "Off in your phone's settings. Turn this on to open {platform}.": "Desativadas nas configurações do celular. Ative isto para abrir {platform}.",
 "Off keeps the market and sells to its countries as your home market.": "Desativado mantém o mercado e vende para os países dele como o mercado principal.",
 "Off keeps this page out of Google and out of your sitemap.": "Desativado, esta página fica fora do Google e do seu sitemap.",
 "Off one of it.": "Em uma unidade.",
 "Off sale": "Fora de venda",
 "Off to keep stock here without shipping from it.": "Desative para guardar estoque aqui sem enviar daqui.",
 "Off to keep this location without shipping from it or offering pickup.": "Desative para manter este local sem enviar dele nem oferecer retirada.",
 "Off topic": "Fora do tema",
 "Off, buyers pay your prices and nothing more.": "Desativado, os compradores pagam seus preços e nada mais.",
 "Off, each order is made in CJ unpaid, and waits until you pay it there. On, it is confirmed and paid from your CJ balance as soon as your buyer pays.": "Desativado, cada pedido é criado no CJ sem pagamento e espera você pagar lá. Ativado, é confirmado e pago com seu saldo CJ assim que o comprador pagar.",
 "Off, each order waits in {name} as a draft until you approve it there, and {name2} charges you only then. On, it is made and charged as soon as it is paid.": "Desativado, cada pedido espera no {name} como rascunho até você aprovar lá, e o {name2} só cobra você nesse momento. Ativado, é criado e cobrado assim que for pago.",
 "Off, it follows your store setting: {value}{value2}.": "Desativado, segue a configuração da loja: {value}{value2}.",
 "Off, it stays on your list and on your products, and isn't offered for new ones.": "Desativado, continua na sua lista e nos seus produtos, mas não é oferecido para os novos.",
 "Off, its countries see your home market.": "Desativado, os países veem seu mercado principal.",
 "Off, the order page has no return button.": "Desativado, a página do pedido não tem botão de devolução.",
 "Off. Sign-ups are still recorded.": "Desativada. Os cadastros continuam sendo registrados.",
