 "On any post or comment by a member ranked below them.": "Em qualquer publicação ou comentário de um membro de nível inferior.",
 "On every page: your website, your storelib.com page and products, your OnePage, checkout and the thank you page, with product views, add to cart, checkout and purchases.": "Em todas as páginas: seu site, sua página e produtos na storelib.com, sua OnePage, o checkout e a página de agradecimento, com visualizações de produto, itens no carrinho, checkout e compras.",
