 "On. New people start it from now.": "Ativada. Pessoas novas começam a partir de agora.",
 "Onboarding reminders": "Lembretes de início",
 "Once it has passed, say": "Depois que passar, mostrar",
 "Once it is available you can cash it out, and it usually reaches your bank in 1 to 3 business days.": "Quando estiver disponível, você pode sacar, e costuma chegar ao banco em 1 a 3 dias úteis.",
 "Once it starts it cannot be taken back. You can stop the ones not yet sent.": "Depois de começar, não dá para desfazer. Você pode parar os que ainda não foram enviados.",
 "Once per person": "Uma vez por pessoa",
 "Once saved, they'll appear on your OnePage.": "Depois de salvas, elas aparecem na sua OnePage.",
 "Once the items are back, mark them received: you choose whether they go back into stock, and you refund the buyer from the same screen.": "Quando os itens voltarem, marque como recebidos: você escolhe se voltam ao estoque e reembolsa o comprador na mesma tela.",
 "One a line, for example\nfree followers\ncrypto signal*": "Uma por linha, por exemplo\nseguidores grátis\nsinal cripto*",
 "One email a day at most, listing what sold down to its low stock line.": "No máximo um e-mail por dia, listando o que chegou ao limite.",
 "One email an hour later with a link back to what they chose, only to buyers who ticked the news box. It stops the moment they buy.": "Um e-mail uma hora depois com um link para o que escolheram, só para quem marcou a caixa de novidades. Para assim que compram.",
 "One email an hour later, only to buyers who ticked the news box. With the news box hidden nobody can tick it, so no reminder goes out.": "Um e-mail uma hora depois, só para quem marcou a caixa de novidades. Com a caixa oculta ninguém pode marcar, então nenhum lembrete é enviado.",
 "One event has a price, and nobody can buy a ticket until payouts are connected.": "Um evento tem preço e ninguém pode comprar ingresso até os repasses serem conectados.",
 "One event has a ticket price, but payouts are not connected, so nobody can buy it.": "Um evento tem preço de ingresso, mas os repasses não estão conectados, então ninguém pode comprar.",
