 "Only approved translations show, and only once a language is published. Anything not translated yet shows in your default language, never blank.": "Só traduções aprovadas aparecem, e só depois que o idioma é publicado. O que ainda não foi traduzido aparece no idioma padrão, nunca em branco.",
