 "Only orders placed after you turn the app on are asked. Buyers who turned review emails off, or already reviewed, are never asked.": "Só pedidos feitos depois de ativar o app recebem o pedido. Compradores que desativaram os e-mails de avaliação, ou que já avaliaram, nunca são convidados.",
 "Only people who asked for your news get it.": "Só recebe quem pediu suas novidades.",
 "Only people who trigger it after you turn it on are sent anything. Someone who unsubscribes is never sent another email, wherever they are in the flow.": "Só recebe algo quem acionar depois que você ativar. Quem se descadastra nunca recebe outro e-mail, em qualquer ponto do fluxo.",
