 "Optional. Visitors from other countries see prices converted to their currency. Checkout always charges {currency}.": "Opcional. Visitantes de outros países veem os preços convertidos para a moeda deles. O checkout sempre cobra em {currency}.",
 "Optional. Visitors from other countries see your prices in their currency and pay in it.": "Opcional. Visitantes de outros países veem seus preços na moeda deles e pagam nela.",
 "Optional. Visitors in the countries you list see prices in that currency and pay in it. Everyone else sees {currency}. Anyone can switch with your website's currency selector.": "Opcional. Visitantes dos países que você listar veem os preços nessa moeda e pagam nela. Os demais veem {currency}. Qualquer pessoa pode trocar no seletor de moeda do seu site.",
 "Optional. Visitors in these countries see your prices in their currency, can switch with your website's currency selector, and pay in it.": "Opcional. Visitantes desses países veem seus preços na moeda deles, podem trocar pelo seletor de moeda do seu site e pagam nela.",
