 "Stored encrypted and never shown again.": "Guardada criptografada e nunca mais mostrada.",
 "Storelib AI": "Storelib AI",
 "Storelib AI could not be reached. Check your connection and try again.": "Não foi possível acessar a Storelib AI. Verifique a conexão e tente de novo.",
 "Storelib AI is already included in your plan. Connect your own Claude or OpenAI API key to use your account for that provider without counting those edits against your plan.": "O Storelib AI já está incluído no seu plano. Conecte sua própria chave de API do Claude ou da OpenAI para usar sua conta nesse provedor sem que essas edições contem no seu plano.",
 "Storelib AI is already included in your plan. If you would rather it ran on your own OpenAI key, connect it here and those edits stop counting against your plan's AI edits.": "A Storelib AI já está incluída no seu plano. Se preferir que ela use sua própria chave da OpenAI, conecte aqui e essas edições deixam de contar nas edições de IA do plano.",
 "Storelib AI is busy right now. Try again in a moment.": "A Storelib AI está ocupada agora. Tente de novo daqui a pouco.",
 "Storelib AI isn't available right now. You can still translate each text yourself.": "A Storelib AI não está disponível agora. Você ainda pode traduzir cada texto.",
 "Storelib AI now answers on your account. Your key is used for your chats only, kept encrypted, and never shown again.": "A Storelib AI agora responde pela sua conta. Sua chave é usada só nos seus chats, fica criptografada e nunca mais é mostrada.",
 "Storelib AI reads these before every change on every one of your websites. Tell it “remember this” in the builder, or add one here.": "A Storelib AI lê isto antes de cada alteração em todos os seus sites. Diga “lembre disso” no editor ou adicione aqui.",
 "Storelib Help Center": "Central de ajuda da Storelib",
 "Storelib Payments": "Storelib Payments",
 "Storelib Reviews is on": "O Storelib Reviews está ativado",
 "Storelib Reviews needs its database update (SQL part 134). Until it runs, nothing here is kept.": "O Storelib Reviews precisa da atualização do banco de dados (parte SQL 134). Até lá, nada aqui é salvo.",
 "Storelib address": "Endereço Storelib",
 "Storelib adds the package's empty weight to the products inside when it works out a weight based shipping rate, so the buyer pays for what the parcel really weighs.": "A Storelib soma o peso vazio do pacote aos produtos ao calcular uma tarifa por peso, para o comprador pagar pelo peso real do pacote.",
 "Storelib apps": "Apps da Storelib",
 "Storelib apps and the services you already use.": "Apps da Storelib e os serviços que você já usa.",
 "Storelib badge hidden": "Selo da Storelib oculto",
 "Storelib badge shown": "Selo da Storelib visível",
 "Storelib can't reach your repository": "A Storelib não consegue acessar seu repositório",
 "Storelib can't take card payments in {local} yet, so your store sells in {currency}.": "O Storelib ainda não aceita pagamentos com cartão em {local}, então sua loja vende em {currency}.",
 "Storelib cannot see any repositories. Give it access to one on GitHub, then": "A Storelib não vê nenhum repositório. Dê acesso a um no GitHub e depois",
 "Storelib charges what you set and nothing more. Ask an accountant which rates apply to you.": "A Storelib cobra o que você define e nada mais. Pergunte a um contador quais alíquotas se aplicam a você.",
 "Storelib charges what you set here and nothing more. Check which rates apply to you with an accountant.": "A Storelib cobra o que você define aqui e nada mais. Confirme com um contador quais alíquotas se aplicam a você.",
 "Storelib couldn't open your site to take the push": "A Storelib não conseguiu abrir seu site para receber o push",
 "Storelib couldn't sign in to your repository. Reconnect GitHub and try again. Nothing on your site was lost.": "A Storelib não conseguiu entrar no repositório. Reconecte o GitHub e tente de novo. Nada do site se perdeu.",
 "Storelib didn't answer": "A Storelib não respondeu",
 "Storelib doesn't take changes to this file": "A Storelib não aceita mudanças neste arquivo",
 "Storelib fee": "Taxa do Storelib",
 "Storelib includes it in the answer to the bank.": "O Storelib inclui isso na resposta ao banco.",
 "Storelib is answering the bank. Add anything that proves the sale so it can be sent with the response.": "A Storelib está respondendo ao banco. Adicione o que comprove a venda para enviar junto com a resposta.",
 "Storelib is helping with this case. Its messages go to you and the buyer.": "O Storelib está ajudando neste caso. As mensagens vão para você e para o comprador.",
 "Storelib is not allowed to use the microphone. Allow Microphone in Storelib's app permissions, then try again.": "A Storelib não tem permissão para usar o microfone. Permita o microfone nas permissões do app da Storelib e tente de novo.",
