 "The editor opens in your default language and currency. Switch them with your theme's own language and currency selectors on the page, as visitors do.": "O editor abre no seu idioma e moeda padrão. Troque-os com os seletores de idioma e moeda do seu tema na página, como os visitantes fazem.",
 "The editor, the preview and your website all open in your default language and your store currency. Switch them with your theme's own selectors on the page, as visitors do.": "O editor, a prévia e o seu site abrem no idioma padrão e na moeda da sua loja. Troque com os seletores do seu tema na página, como os visitantes.",
 "The email": "O e-mail",
