 "This publish will not be backed up. Run supabase/sql/RUN_THEME_BACKUPS.sql once to turn backups on.": "Esta publicação não terá backup. Rode supabase/sql/RUN_THEME_BACKUPS.sql uma vez para ativar os backups.",
 "This records the cash you gave back. Nothing is sent to a card, and the buyer gets an email about it.": "Isso registra o dinheiro que você devolveu. Nada é enviado a um cartão, e o comprador recebe um e-mail sobre isso.",
