 "Visitors": "Visitantes",
 "Visitors are matched by the country they browse from, and can change it with the currency or country selector. Their choice is remembered.": "Os visitantes são associados pelo país de onde navegam e podem mudar com o seletor de moeda ou país. A escolha é lembrada.",
 "Visitors are matched by the country they browse from, and can change it with the currency selector. Their choice is remembered.": "Os visitantes são identificados pelo país de onde navegam e podem mudar isso no seletor de moeda. A escolha fica salva.",
 "Visitors confirm before it opens": "Os visitantes confirmam antes de abrir",
 "Visitors go to {goesTo} for 30 days, then it stops.": "Os visitantes vão para {goesTo} por 30 dias, depois para.",
 "Visitors in the EU, the UK and Switzerland are counted in full once they accept cookies; before that Google gets a cookieless ping.": "Visitantes da UE, do Reino Unido e da Suíça são contados por completo quando aceitam os cookies; antes disso, o Google recebe um ping sem cookies.",
 "Visitors may see a different order depending on their location or preferences.": "Os visitantes podem ver outra ordem conforme a localização ou preferências.",
 "Visitors see a placeholder until you publish again.": "Os visitantes veem uma página provisória até você publicar de novo.",
 "Visitors see a placeholder. {name} was the last one live.": "Os visitantes veem uma página provisória. {name} foi o último no ar.",
