 "Visitors switch with your theme's language selector. Turn on Show visitors their own language to open a first visit in their browser's language.": "Os visitantes trocam com o seletor de idioma do seu tema. Ative Mostrar aos visitantes o próprio idioma para abrir a primeira visita no idioma do navegador.",
