 "What you hear about": "Sobre o que você fica sabendo",
 "What you pick when you refund an order. It stays on the order's timeline.": "O que você escolhe ao reembolsar um pedido. Fica na linha do tempo do pedido.",
 "What you price in. Visitors anywhere not listed under More currencies see prices in it and pay in it.": "A moeda dos seus preços. Visitantes de qualquer lugar fora de Mais moedas veem os preços nela e pagam nela.",
 "What you price in. Visitors in {country}, and anywhere not listed under More currencies, see prices in it and pay in it.": "A moeda dos seus preços. Visitantes em {country}, e em qualquer lugar fora de Mais moedas, veem os preços nela e pagam nela.",
 "What you will cover and who it is for": "O que você vai abordar e para quem é",
 "What you wrote in this email is replaced.": "O que você escreveu neste e-mail é substituído.",
 "What your buyers get from you, and when. Open one to see it and change its words. Each goes out with your store's name, and a reply comes to your contact email.": "O que seus compradores recebem de você, e quando. Abra um para ver e mudar o texto. Cada um sai com o nome da sua loja, e as respostas vão para seu e-mail de contato.",
 "What your completed sales took in over this period, before fees and refunds.": "O que suas vendas concluídas renderam neste período, antes de taxas e reembolsos.",
