 "When": "Quando",
 "When a buyer asks to return items, so they know it arrived.": "Quando um comprador pede a devolução, para saber que chegou.",
 "When a buyer has a problem with an order (it hasn't arrived, it came damaged, they want a refund), they ask from their order page and it lands here and in your email. You answer first; either of you can ask Storelib to step in.": "Quando um comprador tem um problema com um pedido (não chegou, chegou danificado, quer reembolso), ele pede pela página do pedido e chega aqui e no seu e-mail. Você responde primeiro; qualquer um dos dois pode pedir ao Storelib para intervir.",
 "When a draft was last changed.": "Quando um rascunho foi alterado pela última vez.",
 "When a review comes in": "Quando chega uma avaliação",
 "When a shipment is marked as failed: the carrier, or your own delivery, couldn't deliver it.": "Quando um envio é marcado como falho: a transportadora, ou sua entrega própria, não conseguiu entregar.",
 "When a store's owner invites you, it shows here and you can open it from your own account.": "Quando o dono de uma loja convidar você, ela aparece aqui e você pode abri-la pela sua conta.",
 "When buyers can come. Shown at checkout and in the pickup email.": "Quando os compradores podem vir. Mostrado no checkout e no e-mail de retirada.",
 "When does Pro pay for itself?": "Quando o Pro se paga?",
 "When it pushes to": "Quando ele fizer push para",
 "When it pushes to {branch}, the change shows here as a draft within seconds.": "Quando ele fizer push em {branch}, a mudança aparece aqui como rascunho em segundos.",
 "When it's marked delivered.": "Quando é marcado como entregue.",
 "When members leave they can say why. Their answers show up here.": "Quando os membros saem, podem dizer o motivo. As respostas aparecem aqui.",
 "When members report a post, a comment or somebody, it lands here.": "Quando os membros denunciam uma publicação, um comentário ou alguém, chega aqui.",
 "When pressed": "Ao tocar",
 "When returns are on, a buyer sees Request a return on their order page for as many days as your return window.": "Com devoluções ativadas, o comprador vê Pedir devolução na página do pedido pelo número de dias do seu prazo.",
 "When somebody writes to you through the contact form on your website, the message shows here and in your email.": "Quando alguém escreve pelo formulário de contato do seu site, a mensagem aparece aqui e no seu e-mail.",
 "When someone joins your list": "Quando alguém entra na sua lista",
