 "When you publish changes, new and edited text is translated into your other languages within a few minutes. Translations you edit yourself are never replaced.": "Ao publicar alterações, o texto novo e editado é traduzido para seus outros idiomas em alguns minutos. As traduções que você mesmo edita nunca são substituídas.",
